<script>
document.addEventListener('DOMContentLoaded',()=>{const form=document.getElementById('asset-registration-form'),pages=[...document.querySelectorAll('.wizard-page')],tabs=[...document.querySelectorAll('#wizard-progress button')],prev=document.getElementById('wizard-prev'),next=document.getElementById('wizard-next'),submit=document.getElementById('wizard-submit');let step=0;const titles=['Identification & Classification','Location & Asset Hierarchy','Technical Profile','Lifecycle, Ownership & Warranty','Review & Submit'];const show=n=>{step=Math.max(0,Math.min(4,n));pages.forEach((p,i)=>p.classList.toggle('active',i===step));tabs.forEach((b,i)=>{b.classList.toggle('active',i===step);b.classList.toggle('done',i<step)});document.getElementById('wizard-title').textContent=titles[step];prev.disabled=step===0;next.style.display=step===4?'none':'inline-block';submit.style.display=step===4?'inline-block':'none';if(step===4){const g=document.getElementById('review-grid');g.innerHTML='';['customer_id','customer_site_id','name','asset_category','asset_type','criticality','ownership_type','maintenance_strategy'].forEach(n=>{const e=form.querySelector(`[name="${n}"]`);let v=e?.value||'Not set';if(e?.tagName==='SELECT'&&e.selectedIndex>=0)v=e.options[e.selectedIndex].text;g.innerHTML+=`<div class="review-item"><small>${n.replaceAll('_',' ')}</small><b>${v}</b></div>`})}};tabs.forEach((b,i)=>b.onclick=()=>show(i));prev.onclick=()=>show(step-1);next.onclick=()=>{const bad=[...pages[step].querySelectorAll('[required]')].find(e=>!e.checkValidity());if(bad)return bad.reportValidity();show(step+1)};show(0);
const c=document.getElementById('asset-customer-select'),s=document.getElementById('asset-site-select'),p=document.getElementById('asset-parent-select'),l=document.getElementById('asset-location-select');const rel=()=>{const cv=c.value,sv=s.value;[...s.options].forEach(o=>{if(o.value){o.hidden=o.dataset.customerId!==cv;o.disabled=o.hidden}});[...(p?.options||[])].forEach(o=>{if(o.value){o.hidden=o.dataset.customerId!==cv||o.dataset.siteId!==sv;o.disabled=o.hidden}});[...(l?.options||[])].forEach(o=>{if(o.value){o.hidden=o.dataset.customerId!==cv||o.dataset.siteId!==sv;o.disabled=o.hidden}})};c?.addEventListener('change',()=>{s.value='';rel()});s?.addEventListener('change',rel);rel();
const t=document.getElementById('asset-template-select'),wrap=document.getElementById('dynamic-spec-fields'),empty=document.getElementById('dynamic-spec-empty'),json=document.getElementById('technical-specifications-json');const sync=()=>{const d={};wrap.querySelectorAll('[data-key]').forEach(i=>{if(i.value)d[i.dataset.key]=i.value});json.value=Object.keys(d).length?JSON.stringify(d):''};const render=()=>{wrap.innerHTML='';let schema={};try{schema=JSON.parse(t.options[t.selectedIndex]?.dataset.schema||'{}')}catch(e){};const entries=Object.entries(schema);empty.style.display=entries.length?'none':'block';entries.forEach(([k,d])=>{d=typeof d==='object'&&d?d:{};const box=document.createElement('div');box.className='field';box.innerHTML=`<label>${d.label||k.replaceAll('_',' ')}</label>`;let i;if(Array.isArray(d.options)){i=document.createElement('select');i.innerHTML='<option value="">Select</option>'+d.options.map(v=>`<option>${v}</option>`).join('')}else{i=document.createElement('input');i.type=d.type==='number'?'number':'text'}i.dataset.key=k;i.onchange=sync;i.oninput=sync;box.append(i);wrap.append(box)});sync()};t?.addEventListener('change',render);render();
const q=document.getElementById('registry-search'),st=document.getElementById('registry-status'),cr=document.getElementById('registry-criticality'),cards=[...document.querySelectorAll('.asset')];const filter=()=>cards.forEach(x=>x.style.display=(!q.value||x.dataset.search.includes(q.value.toLowerCase()))&&(!st.value||x.dataset.status===st.value)&&(!cr.value||x.dataset.criticality===cr.value)?'flex':'none');q.oninput=filter;st.onchange=filter;cr.onchange=filter;});
</script>
